/**
 * Библиотека Псайканы (психосилы) — Warhammer DBC.
 *
 * Данные книги. Содержимое компендиума "warhammer-dbc.psychic-powers" живёт
 * в packs-src/psychic-powers/ и собирается из него (этап 4 плана); поле
 * folder[] здесь задаёт путь вложенной папки.
 *
 * Структура папок (по скриншотам):
 *   ПСИХОСИЛЫ → ТАУМАТУРГИЯ / КОЛДОВСТВО / ВЫСШЕЕ КОЛДОВСТВО / ДЕМОНОЛОГИЯ
 *   ФУНДАМЕНТАЛЬНЫЕ ДИСЦИПЛИНЫ → ТЕЛЕКИНЕЗ / ТЕЛЕПАТИЯ / ПРОРИЦАНИЕ /
 *                                БИОМАНТИЯ / ПИРОМАНТИЯ
 *   БОЖЕСТВЕННЫЕ ДИСЦИПЛИНЫ → Слаанеш / Нургл / Тзинч
 *   РЕДКИЕ ДИСЦИПЛИНЫ → Хрономантия / Криомантия / …
 *
 * Метаданные раскладываются по полям psychicPower (cost, prRequired, testMod,
 * action, range, powerType, damage…). Точная форма психотеста (vs/режимы) и
 * требования сохраняются в тексте effect, чтобы ничего не терялось.
 */

const IMG = "icons/svg/daze.svg";

// powerType: attack|aura|infusion|duration|change|touch|indirect|summon|
//            psychicBlade|psychicShoot|concentration|cycle|other
// o: { xp, pr, test, act, rng, pt, sus, dmg, dmgT, pen, fx }
function P(name, o) {
  return {
    name, type: "psychicPower", img: IMG,
    system: {
      description: "", notes: "", cost: o.xp ?? 0,
      discipline: "", subtype: "", powerType: o.pt || "other",
      extraTypes: [], shootSubtype: "",
      prRequired: o.pr ?? 1, testChar: o.tc || "wp", testMod: o.test ?? 0,
      action: o.act || "half", range: o.rng || "",
      sustainable: !!o.sus, sustainCost: 1, sustainAction: "free",
      damage: o.dmg || "", damageType: o.dmgT || "energy", penetration: o.pen ?? 0,
      weaponProps: [], charDamageStat: "", charDamageFormula: "",
      profiles: [], variants: [],
      effect: o.fx || "", isSustained: false,
      effects: {
        charBonusStat: "", charBonusValue: 0, charBonuses: [],
        armourAll: 0, fearRating: 0, sizeMod: 0, grantedTraits: "",
        weaponBuff: { enabled: false, scope: "equipped", damageMod: 0, penMod: 0, rangeMod: 0, addProps: [] }
      }
    }
  };
}
// Дисциплина (ключ PSY_DISCIPLINES) по названию папки 2-го уровня.
const DISC_BY_FOLDER = {
  "ТАУМАТУРГИЯ": "thaumaturgy", "КОЛДОВСТВО": "sorcery",
  "ВЫСШЕЕ КОЛДОВСТВО": "highSorcery", "ДЕМОНОЛОГИЯ": "daemonology",
  "ТЕЛЕКИНЕЗ": "telekinesis", "ТЕЛЕПАТИЯ": "telepathy",
  "ПРОРИЦАНИЕ": "divination", "БИОМАНТИЯ": "biomancy", "ПИРОМАНТИЯ": "pyromancy",
  "Слаанеш": "slaanesh", "Нургл": "nurgle", "Тзинч": "tzeentch",
  "Хрономантия": "chronomancy", "Криомантия": "cryomancy", "Техномантия": "technomancy",
  "Геомантия": "geomancy", "Фульминация": "fulmination", "Умбрамантия": "umbramancy",
  "Либрариум": "librarium", "Магия Крови": "bloodMagic"
};
// Правка подтипа, где имя листовой папки расходится с подписью подтипа.
const SUBTYPE_FIX = {
  "Малые Психосилы": "Малые психосилы", "Колдовской Клинок": "Колдовской клинок",
  "Амальгамы 1": "Амальгамы", "Амальгамы 2": "Амальгамы"
};
// grp заодно проставляет discipline + subtype по пути папки.
const grp = (folder, arr) => {
  const discipline = DISC_BY_FOLDER[folder[1]] || "";
  const leaf = folder[folder.length - 1];
  const subtype = SUBTYPE_FIX[leaf] ?? (folder.length > 2 ? leaf : "");
  return arr.map(p => ({ ...p, folder, system: { ...p.system, discipline, subtype } }));
};

